        string prefix = strs[0];

        if(strs.size() == 1)
            return prefix;

        for(int i = 1; i < strs.size(); i++){

            int n = min(prefix.size(), strs[i].size());
            prefix.resize(n);

            string ans = "";

            for(int j = 0; j < n; j++){

                if(prefix[j] != strs[i][j])
                    break;

                ans.push_back(prefix[j]);

            }
            prefix = ans;

        }

        return prefix;
    }
};

class Trie {
public:
    /** Initialize your data structure here. */
    static const int ALPHA_SIZE = 26;
    Trie* character[ALPHA_SIZE];
    bool endOfWord;
    Trie() {
        this -> endOfWord = false;
        for (int i = 0; i < ALPHA_SIZE; i++) {
            this -> character[i] = nullptr;
        }
    }

    /** Inserts a word into the trie. */
    void insert(string word) {
        Trie* curr = this;
        for (int i = 0; i < word.size(); i++) {
            if (curr -> character[word[i] - 'a'] == nullptr) {
                curr -> character[word[i] - 'a'] = new Trie();
            }
            curr = curr -> character[word[i] - 'a'];
        }
        curr -> endOfWord = true;
    }

    /** Returns if the word is in the trie. */
    bool search(string word) {
        if (this == nullptr) {
            return false;
        }
        Trie* curr  = this;
        for (int i = 0; i < word.size(); i++) {
            curr = curr -> character[word[i] - 'a'];
            if (curr == nullptr) {
                return false;
            }
        }
        return curr -> endOfWord;
    }

    /** Returns if there is any word in the trie that starts with the given prefix. */
    bool startsWith(string prefix) {
        if (this == nullptr) {
            return false;
        }
        Trie* curr  = this;
        for (int i = 0; i < prefix.size(); i++) {
            curr = curr -> character[prefix[i] - 'a'];
            if (curr == nullptr) {
                return false;
            }
        }
        return true;
    }
};

