    string longestCommonPrefix(vector<string>& strs) {
        if(strs.size()==0)
            return "";
        string ans="";
        int n=strs.size();
        sort(strs.begin(),strs.end());
        string s=strs[0],e=strs[n-1];
        for(int i=0;i<s.size();i++)
        {
            if(e[i]==s[i])
                ans+=s[i];
            else
                break;
        }
        return ans;
    }
};

